<?php require_once 'includes/db.php';require_once 'includes/auth.php';$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['name']);$email=trim($_POST['email']);$phone=trim($_POST['phone']);$interest=trim($_POST['interest']);$s=$conn->prepare('INSERT INTO volunteers(name,email,phone,interest) VALUES(?,?,?,?)');$s->bind_param('ssss',$name,$email,$phone,$interest);$s->execute();$msg='Volunteer registration submitted.';} $page_title='Volunteer';include 'includes/header.php';?><div class="card form-card"><h2>Become a Volunteer</h2><?php if($msg):?><div class="alert success-msg"><?=e($msg)?></div><?php endif;?><form method="post"><div class="form-group"><label>Name</label><input name="name" required></div><div class="form-group"><label>Email</label><input type="email" name="email" required></div><div class="form-group"><label>Phone</label><input name="phone" required></div><div class="form-group"><label>Area of Interest</label><input name="interest" placeholder="Events, teaching, food distribution..."></div><button class="btn" type="submit">Register as Volunteer</button></form></div><?php include 'includes/footer.php';?>
